),
"book" AS (
  SELECT r."site_id", (t."ord" - 1)::int AS "idx", t."cell"::int AS "cell"
  FROM "book_raw" r, unnest(string_to_array(r."cells"::text, ',')) WITH ORDINALITY AS t("cell", "ord")
),
"camps" AS (
  SELECT (i * 7 + 3) % 25 AS "x", (i * 5 + 2) % 20 AS "y" FROM generate_series(0, 8) AS i
),
"tiles" AS (
  SELECT gx AS "x", gy AS "y",
         CASE WHEN gx % 5 = 0 AND gy % 5 = 0 THEN 1
              WHEN gx % 3 = 0 AND gy % 3 = 0 THEN 2
              WHEN gx % 2 = 0 AND gy % 2 = 0 THEN 3
              ELSE 4 END AS "pass"
  FROM generate_series(0, 24) AS gx, generate_series(0, 19) AS gy
),
"fill" AS (
  SELECT t."x", t."y", (row_number() OVER (ORDER BY t."pass", t."y", t."x") - 1)::int AS "idx"
  FROM "tiles" t
  WHERE NOT EXISTS (SELECT 1 FROM "camps" c WHERE c."x" = t."x" AND c."y" = t."y")
)
UPDATE "plots" p SET "earth_cell" = b."cell"
FROM "valleys" v, "fill" f, "book" b
WHERE p."valley_id" = v."id"
  AND f."x" = p."x" AND f."y" = p."y"
  AND b."site_id" = v."site_id" AND b."idx" = f."idx";--> statement-breakpoint
-- FAIL LOUD, AND SAY WHICH ROW. Without this the next statement reports only
-- "column earth_cell contains null values", which does not tell an operator that
-- somebody's base sits on a tile a PvE camp later took over, or that Earth ran out.
DO $$
DECLARE
  n bigint;
  detail text;
BEGIN
  SELECT count(*), string_agg(format('site %s tile %s,%s', v."site_id", p."x", p."y"), '; ')
    INTO n, detail
    FROM "plots" p JOIN "valleys" v ON v."id" = p."valley_id"
    WHERE p."earth_cell" IS NULL;
  IF n > 0 THEN
    RAISE EXCEPTION 'earth_cell backfill left % plot(s) with no address: %', n, detail
      USING HINT = 'each one is either on a PvE camp tile (camps hold a grid tile but are '
                   'not deeded land, so they have no Earth cell) or in a valley past the '
                   'last patch (Earth seats 120 valleys). Resolve the row, then re-run.';
  END IF;
END $$;--> statement-breakpoint
ALTER TABLE "plots" ALTER COLUMN "earth_cell" SET NOT NULL;--> statement-breakpoint
-- Two parcels on one Earth cell would be two deeds conveying one 55 km county.
-- The DB is the only layer that can actually refuse it. EARTH-ONLY on purpose:
-- cell ids are mask-relative, so a second body turns this into
-- UNIQUE (planet, earth_cell), exactly as valleys_site_id_uq just became composite.
ALTER TABLE "plots" ADD CONSTRAINT "plots_earth_cell_uq" UNIQUE("earth_cell");--> statement-breakpoint
-- THE PLANET DIMENSION (§5.3). 0 = Earth and nothing writes anything else yet;
-- it exists now because Earth is finite (120 valleys / 58,920 parcels) and a second
-- body must be a new mask plus rows at planet_id = 1 — no schema rewrite, no
-- migration of Earth's rows. Site ids are unique WITHIN a body, so the constraint
-- becomes composite; its NAME is deliberately unchanged (see the header).
ALTER TABLE "valleys" ADD COLUMN "planet_id" smallint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "valleys" DROP CONSTRAINT "valleys_site_id_uq";--> statement-breakpoint
ALTER TABLE "valleys" ADD CONSTRAINT "valleys_site_id_uq" UNIQUE("planet_id","site_id");
